LOCALES = ["en", "ar", "br", "bs", "da", "de", "es", "fr", "ja", "ko", "no", "pl", "ru", "th", "tr", "uk", "zh", "zht"]
base = os.path.join(os.path.dirname(__file__), "..", "packages", "app", "src", "i18n")
en_map = dict(KEYS)

for locale in LOCALES:
    path = os.path.join(base, f"{locale}.ts")
    with open(path, "r", encoding="utf-8") as fh:
        content = fh.read()
    if '"exam.type.multiple"' in content:
        print(f"{locale}: already present, skipping")
        continue
    lines = ["", "  // --- exam workspace / book pdf panel / remote session dialog (2026-11-23) ---"]
    for key, en_text in KEYS:
        value = T.get(locale, {}).get(key, en_text)
        lines.append(f'  "{key}": {json.dumps(value, ensure_ascii=False)},')
    block = "\n".join(lines) + "\n"
    idx = content.rstrip().rfind("\n}")
    content = content[:idx] + "\n" + block + content[idx + 1:]
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(content)
    print(f"{locale}: +{len(KEYS)} keys")
print("done")
